			discountedSubtotal += int64(math.Round(float64(line.Price) * float64(line.Qty) / 100 * float64(100-discountBP)/100))
		} else {
			discountedSubtotal += int64(math.Round(float64(line.Price) * float64(line.Qty) / 100))
		}
	}

	// Sum discounted subtotal and add tax
	total := discountedSubtotal + int64(math.Round(float64(taxBP) / 100))

	return total
}

